out = [[8]*23 for _ in range(27)]
# Draw the four 11x5 framed panels.
panels = [(1, 2), (7, 4), (13, 3), (19, 1)]  # top row, color
for r0, color in panels:
    for c in range(1, 12):
        out[r0][c] = color
        out[r0+4][c] = color
    for r in range(r0, r0+5):
        out[r][1] = color
        out[r][11] = color
# One interior dot per disconnected same-color source component; right-aligned, every other column.
counts = {2: 2, 4: 4, 3: 1, 1: 1}
for r0, color in panels:
    n = counts[color]
    for c in range(9-2*(n-1), 10, 2):
        out[r0+2][c] = color
print('\n'.join(' '.join(map(str,row)) for row in out))
